module div_16bit(
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

reg [15:0] dividend;
reg [7:0] divisor;
reg [15:0] quotient;
reg [15:0] remainder;

always @(A, B) begin
    dividend <= A;
    divisor <= B;
end

always @(dividend, divisor) begin
    if (dividend[15:8] >= divisor) begin
        quotient <= 16'b1;
        remainder <= dividend[15:8] - divisor;
    end else begin
        quotient <= 16'b0;
        remainder <= dividend[15:8];
    end
    if (remainder[15] == 1'b1) begin
        quotient <= {quotient[14:0], 1'b0};
        remainder <= {remainder[14:0], dividend[7]};
    end else begin
        quotient <= {quotient[14:0], 1'b1};
        remainder <= {remainder[14:0], dividend[7]};
    end
end

assign result = quotient;
assign odd = remainder;

endmodule
